16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	import org.springframework.samples.petclinic.util.Luhn;
20	import org.springframework.samples.petclinic.util.RegistrationDatePolicy;
21	
22	import jakarta.persistence.*;
23	import jakarta.validation.constraints.NotEmpty;
24	import jakarta.validation.constraints.Pattern;
25	
26	import java.time.LocalDate;
27	import java.time.temporal.ChronoUnit;
28	import java.util.*;
29	
30	/**
31	 * Simple JavaBean domain object representing an owner.
32	 *
33	 * @author Ken Krebs
34	 * @author Juergen Hoeller
35	 * @author Sam Brannen
36	 * @author Michael Isvy
37	 */
38	@Entity
39	@Table(name = "owners")
40	public class Owner extends Person {
41	    @Column(name = "address")
42	    @NotEmpty
43	    private String address;
44	
45	    @Column(name = "city")
46	    @NotEmpty
47	    private String city;
48	
49	    @Column(name = "postcode")
50	    private String postcode;
51	
52	    @Column(name = "telephone")
53	    @NotEmpty
54	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
55	    private String telephone;
56	
57	    @Column(name = "email")
58	    private String email;
59	
60	    @Column(name = "birth_date")
61	    private LocalDate birthDate;
62	
63	    @Column(name = "registration_date")
64	    private LocalDate registrationDate;
65	
66	    @Column(name = "customer_code")
67	    private String customerCode;
68	
69	    @Column(name = "household_id")
70	    private String householdId;
71	
72	    @Column(name = "namesake_count")
73	    private Integer namesakeCount;
74	
75	    @Column(name = "household_size")
76	    private Integer householdSize;
77	
78	    @Column(name = "possible_duplicate")
79	    private Boolean possibleDuplicate;
80	
81	    @Column(name = "possible_duplicate_of")
82	    private Integer possibleDuplicateOf;
83	
84	    /**
85	     * Whether this owner was knowingly created into a shared household (the request declared shared
86	     * membership). A declared member is not treated as a suspected duplicate. Set per request and
87	     * never persisted.
88	     */
89	    @Transient
90	    private boolean declaredHouseholdMember;
91	
92	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
93	    private Set<Pet> pets;
94	
95	    /**
96	     * Resolve the registration date at creation time: default it to the server's
97	     * current date when none was supplied, and roll a weekend date forward to the
98	     * next business day so every value derived from it (such as the membership
99	     * number's year segment) uses the adjusted date.
100	     */
101	    @PrePersist
102	    private void resolveRegistrationDate() {
103	        this.registrationDate = RegistrationDatePolicy.effectiveDate(this.registrationDate);
104	    }
105	
106	    public String getAddress() {
107	        return this.address;
108	    }
109	
110	    public void setAddress(String address) {
111	        this.address = address;
112	    }
113	
114	    public String getCity() {
115	        return this.city;
116	    }
117	
118	    public void setCity(String city) {
119	        this.city = city;
120	    }
121	
122	    public String getPostcode() {
123	        return this.postcode;
124	    }
125	
126	    public void setPostcode(String postcode) {
127	        this.postcode = postcode;
128	    }
129	
130	    /**
131	     * The owner's locality: the region component of its {@link #customerCode}
132	     * identity (see {@link CustomerCode}), or {@code null} when no customer code
133	     * is assigned. The region was derived from the owner's postcode and city when
134	     * the identity was minted, so the locality now follows the identity rather than
135	     * being recomputed from the current city and postcode.
136	     */
137	    public String getLocality() {
138	        return CustomerCode.regionOf(this.customerCode);
139	    }
140	
141	    /**
142	     * The owner's timezone: the IANA name for its {@linkplain #getLocality()
143	     * locality}, from the fixed region-to-timezone table (see
144	     * {@link RegionTimezone}), or {@code null} when the locality is absent or has
145	     * no known timezone.
146	     */
147	    public String getTimezone() {
148	        return RegionTimezone.zoneFor(getLocality());
149	    }
150	
151	    public String getTelephone() {
152	        return this.telephone;
153	    }
154	
155	    public void setTelephone(String telephone) {
156	        this.telephone = telephone;
157	    }
158	
159	    public String getEmail() {
160	        return this.email;
161	    }
162	
163	    public void setEmail(String email) {
164	        this.email = email;
165	    }
166	
167	    public LocalDate getBirthDate() {
168	        return this.birthDate;
169	    }
170	
171	    public void setBirthDate(LocalDate birthDate) {
172	        this.birthDate = birthDate;
173	    }
174	
175	    /**
176	     * The owner's {@link AgeBand age band} on the {@link #registrationDate}, derived
177	     * from the {@link #birthDate}, or {@code null} when no birth date is on file.
178	     */
179	    public AgeBand getAgeBand() {
180	        return AgeBand.on(this.birthDate, this.registrationDate);
181	    }
182	
183	    public LocalDate getRegistrationDate() {
184	        return this.registrationDate;
185	    }
186	
187	    public void setRegistrationDate(LocalDate registrationDate) {
188	        this.registrationDate = registrationDate;
189	    }
190	
191	    public String getCustomerCode() {
192	        return this.customerCode;
193	    }
194	
195	    public void setCustomerCode(String customerCode) {
196	        this.customerCode = customerCode;
197	    }
198	
199	    /**
200	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'}
201	     * where {@code YY} is the last two digits of the {@link #registrationDate}
202	     * year (e.g. {@code "NSW-3F2A9C1D-M26"}). Derived from the owner's own fields.
203	     */
204	    public String getMembershipNumber() {
205	        if (this.customerCode == null || this.registrationDate == null) {
206	            return null;
207	        }
208	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
209	    }
210	
211	    /**
212	     * The Luhn check digit (0-9) computed over the digits of the
213	     * {@link #customerCode}, or {@code null} when no customer code is assigned.
214	     */
215	    public Integer getCheckDigit() {
216	        if (this.customerCode == null) {
217	            return null;
218	        }
219	        return Luhn.checkDigit(this.customerCode);
220	    }
221	
222	    public String getHouseholdId() {
223	        return this.householdId;
224	    }
225	
226	    public void setHouseholdId(String householdId) {
227	        this.householdId = householdId;
228	    }
229	
230	    /**
231	     * The owner's identity key: the single derived value used to detect duplicate owners. It is the
232	     * normalized telephone, the (lower-cased) email or an empty string when absent, and the
233	     * household id or an empty string when absent, joined with {@code '|'} (e.g.
234	     * {@code "+61412345678|jo@example.com|3F2A9C1D4B6E8071"}). Two owners are the same person only
235	     * when their whole identity keys are equal; because the telephone is part of the key, household
236	     * members with different telephones have different keys.
237	     */
238	    public String getIdentityKey() {
239	        return String.join("|",
240	            this.telephone == null ? "" : this.telephone,
241	            this.email == null ? "" : this.email,
242	            this.householdId == null ? "" : this.householdId);
243	    }
244	
245	    /** Tenure, in days, beyond which an owner earns the tenure membership points. */
246	    private static final long TENURE_DAYS_FOR_POINTS = 365;
247	
248	    /** Household size at or above which an owner earns the household membership points. */
249	    private static final int HOUSEHOLD_SIZE_FOR_POINTS = 3;
250	
251	    /**
252	     * The owner's membership points, a score derived from the owner's own
253	     * fields. Starts at {@code 0}, gains {@code 2} when a contact email is on
254	     * file, gains {@code 1} when the owner has no namesakes, gains {@code 2}
255	     * when the owner belongs to a household of {@value #HOUSEHOLD_SIZE_FOR_POINTS}
256	     * or more, and gains {@code 3} when the owner's {@link #getTenureDays()
257	     * tenure} exceeds {@value #TENURE_DAYS_FOR_POINTS} days.
258	     */
259	    public Integer getMembershipPoints() {
260	        int points = 0;
261	        boolean hasEmail = this.email != null && !this.email.isEmpty();
262	        if (hasEmail) {
263	            points += 2;
264	        }
265	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
266	        if (noNamesakes) {
267	            points += 1;
268	        }
269	        boolean largeHousehold = this.householdSize != null && this.householdSize >= HOUSEHOLD_SIZE_FOR_POINTS;
270	        if (largeHousehold) {
271	            points += 2;
272	        }
273	        Long tenureDays = getTenureDays();
274	        if (tenureDays != null && tenureDays > TENURE_DAYS_FOR_POINTS) {
275	            points += 3;
276	        }
277	        return points;
278	    }
279	
280	    /**
281	     * The owner's membership level, a number from 1 to 4 mapped from the owner's
282	     * {@link #getMembershipPoints() membership points}: {@code 1} for 0-1 points,
283	     * {@code 2} for 2-3, {@code 3} for 4-5 and {@code 4} for 6 or more.
284	     */
285	    public Integer getMembershipLevel() {
286	        int points = getMembershipPoints();
287	        if (points <= 1) {
288	            return 1;
289	        }
290	        if (points <= 3) {
291	            return 2;
292	        }
293	        if (points <= 5) {
294	            return 3;
295	        }
296	        return 4;
297	    }
298	
299	    /**
300	     * The owner's tenure: the number of whole days from the {@link #registrationDate}
301	     * to the server's current date, or {@code null} when no registration date is on
302	     * file. Never negative for a registration date that is today or earlier.
303	     */
304	    public Long getTenureDays() {
305	        if (this.registrationDate == null) {
306	            return null;
307	        }
308	        return ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now());
309	    }
310	
311	    /**
312	     * The owner's preferred contact channel, derived from the fields on file:
313	     * {@code "EMAIL"} when a contact email is present, otherwise {@code "PHONE"}.
314	     */
315	    public String getContactPreference() {
316	        boolean hasEmail = this.email != null && !this.email.isEmpty();
317	        return hasEmail ? "EMAIL" : "PHONE";
318	    }
319	
320	    public Integer getNamesakeCount() {
321	        return this.namesakeCount;
322	    }
323	
324	    public void setNamesakeCount(Integer namesakeCount) {
325	        this.namesakeCount = namesakeCount;
326	    }
327	
328	    public Integer getHouseholdSize() {
329	        return this.householdSize;
330	    }
331	
332	    public void setHouseholdSize(Integer householdSize) {
333	        this.householdSize = householdSize;
334	    }
335	
336	    /**
337	     * Whether this owner, while not a declared household member, shares an existing owner's
338	     * last name and postcode but carries a different telephone. Determined once,
339	     * when the owner is created. A declared household member is never a suspected duplicate.
340	     */
341	    public Boolean getPossibleDuplicate() {
342	        return this.possibleDuplicate;
343	    }
344	
345	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
346	        this.possibleDuplicate = possibleDuplicate;
347	    }
348	
349	    /**
350	     * Whether this owner was knowingly created into a shared household. Such a declared member
351	     * bypasses the household-duplicate block and is not flagged as a suspected duplicate.
352	     */
353	    public boolean isDeclaredHouseholdMember() {
354	        return this.declaredHouseholdMember;
355	    }
356	
357	    public void setDeclaredHouseholdMember(boolean declaredHouseholdMember) {
358	        this.declaredHouseholdMember = declaredHouseholdMember;
359	    }
360	
361	    /**
362	     * The id of the existing owner this owner possibly duplicates, or {@code null}
363	     * when it has no such match.
364	     */
365	    public Integer getPossibleDuplicateOf() {
366	        return this.possibleDuplicateOf;
367	    }
368	
369	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
370	        this.possibleDuplicateOf = possibleDuplicateOf;
371	    }
372	
373	    protected Set<Pet> getPetsInternal() {
374	        if (this.pets == null) {
375	            this.pets = new HashSet<>();
376	        }
377	        return this.pets;
378	    }
379	
380	    protected void setPetsInternal(Set<Pet> pets) {
381	        this.pets = pets;
382	    }
383	
384	    public List<Pet> getPets() {
385	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
386	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
387	        return Collections.unmodifiableList(sortedPets);
388	    }
389	
390	    public void setPets(List<Pet> pets) {
391	        this.pets = new HashSet<>(pets);
392	    }
393	
394	    public void addPet(Pet pet) {
395	        getPetsInternal().add(pet);
396	        pet.setOwner(this);
397	    }
398	
399	    /**
400	     * Return the Pet with the given name, or null if none found for this Owner.
401	     *
402	     * @param name to test
403	     * @return true if pet name is already in use
404	     */
405	    public Pet getPet(String name) {
406	        return getPet(name, false);
407	    }
408	
409	    /**
410	     * Return the Pet with the given name, or null if none found for this Owner.
411	     *
412	     * @param name to test
413	     * @return true if pet name is already in use
414	     */
415	    public Pet getPet(String name, boolean ignoreNew) {
416	        name = name.toLowerCase();
417	        for (Pet pet : getPetsInternal()) {
418	            if (!ignoreNew || !pet.isNew()) {
419	                String compName = pet.getName();
420	                compName = compName.toLowerCase();
421	                if (compName.equals(name)) {
422	                    return pet;
423	                }
424	            }
425	        }
426	        return null;
427	    }
428	
429	    public Pet getPet(Integer petId) {
430	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
431	    }
432	
433	    @Override
434	    public String toString() {
435	        return new ToStringCreator(this)
436	
437	            .append("id", this.getId())
438	            .append("new", this.isNew())
439	            .append("lastName", this.getLastName())
440	            .append("firstName", this.getFirstName())
441	            .append("address", this.address)
442	            .append("city", this.city)
443	            .append("telephone", this.telephone)
444	            .append("email", this.email)
445	            .toString();
446	    }
447	}
