package org.springframework.samples.petclinic.model;

import org.springframework.core.style.ToStringCreator;
import org.springframework.samples.petclinic.util.Luhn;
import org.springframework.samples.petclinic.util.RegistrationDatePolicy;

import jakarta.persistence.*;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.Pattern;

import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.*;

/**
 * Simple JavaBean domain object representing an owner.
 *
 * @author Ken Krebs
 * @author Juergen Hoeller
 * @author Sam Brannen
 * @author Michael Isvy
 */
@Entity
@Table(name = "owners")
public class Owner extends Person {
    @Column(name = "address")
    @NotEmpty
    private String address;

    @Column(name = "city")
    @NotEmpty
    private String city;

    @Column(name = "postcode")
    private String postcode;

    @Column(name = "telephone")
    @NotEmpty
    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
    private String telephone;

    @Column(name = "email")
    private String email;

    @Column(name = "birth_date")
    private LocalDate birthDate;

    @Column(name = "registration_date")
    private LocalDate registrationDate;

    @Column(name = "customer_code")
    private String customerCode;

    @Column(name = "household_id")
    private String householdId;

    @Column(name = "namesake_count")
    private Integer namesakeCount;

    @Column(name = "household_size")
    private Integer householdSize;

    @Column(name = "possible_duplicate")
    private Boolean possibleDuplicate;

    @Column(name = "possible_duplicate_of")
    private Integer possibleDuplicateOf;

    /**
     * Whether this owner was knowingly created into a shared household (the request declared shared
     * membership). A declared member is not treated as a suspected duplicate. Set per request and
     * never persisted.
     */
    @Transient
    private boolean declaredHouseholdMember;

    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
    private Set<Pet> pets;

    /**
     * Resolve the registration date at creation time: default it to the server's
     * current date when none was supplied, and roll a weekend date forward to the
     * next business day so every value derived from it (such as the membership
     * number's year segment) uses the adjusted date.
     */
    @PrePersist
    private void resolveRegistrationDate() {
        this.registrationDate = RegistrationDatePolicy.effectiveDate(this.registrationDate);
    }

    public String getAddress() {
        return this.address;
    }

    public void setAddress(String address) {
        this.address = address;
    }

    public String getCity() {
        return this.city;
    }

    public void setCity(String city) {
        this.city = city;
    }

    public String getPostcode() {
        return this.postcode;
    }

    public void setPostcode(String postcode) {
        this.postcode = postcode;
    }

    /**
     * The owner's locality: the region component of its {@link #customerCode}
     * identity (see {@link CustomerCode}), or {@code null} when no customer code
     * is assigned. The region was derived from the owner's postcode and city when
     * the identity was minted, so the locality now follows the identity rather than
     * being recomputed from the current city and postcode.
     */
    public String getLocality() {
        return CustomerCode.regionOf(this.customerCode);
    }

    /**
     * The owner's timezone: the IANA name for its {@linkplain #getLocality()
     * locality}, from the fixed region-to-timezone table (see
     * {@link RegionTimezone}), or {@code null} when the locality is absent or has
     * no known timezone.
     */
    public String getTimezone() {
        return RegionTimezone.zoneFor(getLocality());
    }

    public String getTelephone() {
        return this.telephone;
    }

    public void setTelephone(String telephone) {
        this.telephone = telephone;
    }

    public String getEmail() {
        return this.email;
    }

    public void setEmail(String email) {
        this.email = email;
    }

    public LocalDate getBirthDate() {
        return this.birthDate;
    }

    public void setBirthDate(LocalDate birthDate) {
        this.birthDate = birthDate;
    }

    /**
     * The owner's {@link AgeBand age band} on the {@link #registrationDate}, derived
     * from the {@link #birthDate}, or {@code null} when no birth date is on file.
     */
    public AgeBand getAgeBand() {
        return AgeBand.on(this.birthDate, this.registrationDate);
    }

    public LocalDate getRegistrationDate() {
        return this.registrationDate;
    }

    public void setRegistrationDate(LocalDate registrationDate) {
        this.registrationDate = registrationDate;
    }

    public String getCustomerCode() {
        return this.customerCode;
    }

    public void setCustomerCode(String customerCode) {
        this.customerCode = customerCode;
    }

    /**
     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'}
     * where {@code YY} is the last two digits of the {@link #registrationDate}
     * year (e.g. {@code "NSW-3F2A9C1D-M26"}). Derived from the owner's own fields.
     */
    public String getMembershipNumber() {
        if (this.customerCode == null || this.registrationDate == null) {
            return null;
        }
        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
    }

    /**
     * The Luhn check digit (0-9) computed over the digits of the
     * {@link #customerCode}, or {@code null} when no customer code is assigned.
     */
    public Integer getCheckDigit() {
        if (this.customerCode == null) {
            return null;
        }
        return Luhn.checkDigit(this.customerCode);
    }

    public String getHouseholdId() {
        return this.householdId;
    }

    public void setHouseholdId(String householdId) {
        this.householdId = householdId;
    }

    /**
     * The owner's identity key: the single derived value used to detect duplicate owners. It is the
     * normalized telephone, the (lower-cased) email or an empty string when absent, and the
     * household id or an empty string when absent, joined with {@code '|'} (e.g.
     * {@code "+61412345678|jo@example.com|3F2A9C1D4B6E8071"}). Two owners are the same person only
     * when their whole identity keys are equal; because the telephone is part of the key, household
     * members with different telephones have different keys.
     */
    public String getIdentityKey() {
        return String.join("|",
            this.telephone == null ? "" : this.telephone,
            this.email == null ? "" : this.email,
            this.householdId == null ? "" : this.householdId);
    }

    /** Tenure, in days, beyond which an owner earns the tenure membership points. */
    private static final long TENURE_DAYS_FOR_POINTS = 365;

    /** Household size at or above which an owner earns the household membership points. */
    private static final int HOUSEHOLD_SIZE_FOR_POINTS = 3;

    /**
     * The owner's membership points, a score derived from the owner's own
     * fields. Starts at {@code 0}, gains {@code 2} when a contact email is on
     * file, gains {@code 1} when the owner has no namesakes, gains {@code 2}
     * when the owner belongs to a household of {@value #HOUSEHOLD_SIZE_FOR_POINTS}
     * or more, and gains {@code 3} when the owner's {@link #getTenureDays()
     * tenure} exceeds {@value #TENURE_DAYS_FOR_POINTS} days.
     */
    public Integer getMembershipPoints() {
        int points = 0;
        boolean hasEmail = this.email != null && !this.email.isEmpty();
        if (hasEmail) {
            points += 2;
        }
        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
        if (noNamesakes) {
            points += 1;
        }
        boolean largeHousehold = this.householdSize != null && this.householdSize >= HOUSEHOLD_SIZE_FOR_POINTS;
        if (largeHousehold) {
            points += 2;
        }
        Long tenureDays = getTenureDays();
        if (tenureDays != null && tenureDays > TENURE_DAYS_FOR_POINTS) {
            points += 3;
        }
        return points;
    }

    /**
     * The owner's membership level, a number from 1 to 4 mapped from the owner's
     * {@link #getMembershipPoints() membership points}: {@code 1} for 0-1 points,
     * {@code 2} for 2-3, {@code 3} for 4-5 and {@code 4} for 6 or more.
     */
    public Integer getMembershipLevel() {
        int points = getMembershipPoints();
        if (points <= 1) {
            return 1;
        }
        if (points <= 3) {
            return 2;
        }
        if (points <= 5) {
            return 3;
        }
        return 4;
    }

    /**
     * The owner's tenure: the number of whole days from the {@link #registrationDate}
     * to the server's current date, or {@code null} when no registration date is on
     * file. Never negative for a registration date that is today or earlier.
     */
    public Long getTenureDays() {
        if (this.registrationDate == null) {
            return null;
        }
        return ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now());
    }

    /**
     * The owner's preferred contact channel, derived from the fields on file:
     * {@code "EMAIL"} when a contact email is present, otherwise {@code "PHONE"}.
     */
    public String getContactPreference() {
